import { parseISODate } from "./dates";
import { WORLDLE_SHAPES } from "./content/worldleShapes";

export interface DailyCountry {
  slug: string;
  name: string;
  lat: number;
  lng: number;
  /** SVG path in a 0..100 viewBox — real outline from GeoJSON. */
  svg: string;
}

/**
 * Seven daily countries with real GeoJSON-derived silhouettes, rotating by
 * weekday. Outlines are generated by scripts/gen-worldle-shapes.mjs.
 */
export const WORLDLE_DAILY: DailyCountry[] = [
  { slug: "france", name: "France", lat: 46.2, lng: 2.2, svg: WORLDLE_SHAPES.france },
  { slug: "japan", name: "Japan", lat: 36.2, lng: 138.3, svg: WORLDLE_SHAPES.japan },
  { slug: "italy", name: "Italy", lat: 41.9, lng: 12.6, svg: WORLDLE_SHAPES.italy },
  { slug: "egypt", name: "Egypt", lat: 26.8, lng: 30.8, svg: WORLDLE_SHAPES.egypt },
  { slug: "brazil", name: "Brazil", lat: -14.2, lng: -51.9, svg: WORLDLE_SHAPES.brazil },
  { slug: "australia", name: "Australia", lat: -25.3, lng: 133.8, svg: WORLDLE_SHAPES.australia },
  { slug: "india", name: "India", lat: 22.4, lng: 78.7, svg: WORLDLE_SHAPES.india },
];

export function countryForDate(iso: string): DailyCountry {
  const dow = parseISODate(iso).getUTCDay();
  return WORLDLE_DAILY[dow % WORLDLE_DAILY.length];
}

const toRad = (d: number) => (d * Math.PI) / 180;

export function distanceKm(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number }
): number {
  const R = 6371;
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const la1 = toRad(a.lat);
  const la2 = toRad(b.lat);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(la1) * Math.cos(la2) * Math.sin(dLng / 2) ** 2;
  return Math.round(2 * R * Math.asin(Math.sqrt(h)));
}

/** Compass bearing arrow emoji from a to b. */
export function directionArrow(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number }
): string {
  const y = Math.sin(toRad(b.lng - a.lng)) * Math.cos(toRad(b.lat));
  const x =
    Math.cos(toRad(a.lat)) * Math.sin(toRad(b.lat)) -
    Math.sin(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.cos(toRad(b.lng - a.lng));
  const brng = (Math.atan2(y, x) * 180) / Math.PI;
  const dirs = ["⬆️", "↗️", "➡️", "↘️", "⬇️", "↙️", "⬅️", "↖️"];
  return dirs[Math.round(((brng + 360) % 360) / 45) % 8];
}

/** 0–100 proximity score (100 = correct). Earth's max distance ≈ 20000 km. */
export function proximityPct(km: number): number {
  return Math.max(0, Math.round((1 - km / 20000) * 100));
}
